"""Author neutral controls and exact expected literals before parser execution.

This writes explicitly chosen fixture strings and checks their exact literals;
it does not discover SQL syntax or call any parser/recognizer.
"""
from pathlib import Path
import hashlib
import json

ROOT=Path(__file__).resolve().parent
CASES=[]


def add(dialect,name,sql,decision="admit",reason=None,objects=None,sites=None,**metadata):
    CASES.append(dict(dialect=dialect,id=dialect+"-"+name,sql=sql,expected_decision=decision,expected_reason=reason,object_choices=objects or [],site_choices=sites or [],**metadata))


def object_(kind,name,literal=None,occurrence=0,**extra):
    return dict(kind=kind,name=name,literal=literal or name,occurrence=occurrence,**extra)


def site(name,literal=None,occurrence=0,access="read",binding="unique"):
    return dict(name=name,literal=literal or name,occurrence=occurrence,access=access,expected_binding=binding)


for dialect,q in [("postgresql",'"'),("mysql","`")]:
    table=lambda n:q+n+q
    header=("-- PostgreSQL database dump\n-- Dumped from database version 18.6\n-- Dumped by pg_dump version 18.6\n" if dialect=="postgresql" else "-- MySQL dump 10.13 Distrib 8.0.42, for Linux (x86_64)\n")
    common=dict(source_class="authored-schema",manifest_engine=dialect)
    add(dialect,"simple-table",f"CREATE TABLE {table('parent')} ({table('id')} INTEGER, PRIMARY KEY ({table('id')}));\n",objects=[object_("table","parent",table("parent")),object_("column","id",table("id"),relation="parent"),object_("primary_key","@","PRIMARY KEY",relation="parent",columns=["id"])],**common)
    add(dialect,"nonascii-exact-name",f"CREATE TABLE {table('Équipe')} ({table('clé')} INTEGER);\n",objects=[object_("table","Équipe",table("Équipe")),object_("column","clé",table("clé"),relation="Équipe")],**common)
    add(dialect,"case-distinction",f"CREATE TABLE {table('Foo')} ({table('id')} INTEGER);\nCREATE TABLE {table('foo')} ({table('id')} INTEGER);\n",objects=[object_("table","Foo",table("Foo")),object_("column","id",table("id"),relation="Foo"),object_("table","foo",table("foo")),object_("column","id",table("id"),1,relation="foo")],**common)
    fk=(f"CREATE TABLE {table('parent')} ({table('a')} INTEGER, {table('b')} INTEGER, PRIMARY KEY ({table('a')}, {table('b')}));\n"
        f"CREATE TABLE {table('child')} ({table('x')} INTEGER, {table('y')} INTEGER, CONSTRAINT {table('fk_first')} FOREIGN KEY ({table('x')}, {table('y')}) REFERENCES {table('parent')} ({table('a')}, {table('b')}), CONSTRAINT {table('fk_second')} FOREIGN KEY ({table('y')}, {table('x')}) REFERENCES {table('parent')} ({table('a')}, {table('b')}));\n")
    add(dialect,"ordered-distinct-fks",fk,objects=[object_("table","parent",table("parent")),object_("column","a",table("a"),relation="parent"),object_("column","b",table("b"),relation="parent"),object_("primary_key","@","PRIMARY KEY",relation="parent",columns=["a","b"]),object_("table","child",table("child")),object_("column","x",table("x"),relation="child"),object_("column","y",table("y"),relation="child"),object_("foreign_key","fk_first",table("fk_first"),relation="child",columns=["x","y"],target_relation="parent",target_columns=["a","b"]),object_("foreign_key","fk_second",table("fk_second"),relation="child",columns=["y","x"],target_relation="parent",target_columns=["a","b"])],**common)
    add(dialect,"dialect-missing",f"CREATE TABLE {table('parent')} ({table('id')} INTEGER);\n",decision="refuse",reason="dialect-unavailable",source_class="authored-schema")
    add(dialect,"metadata-conflict",header+f"CREATE TABLE {table('parent')} ({table('id')} INTEGER);\n",decision="refuse",reason="metadata-conflict",source_class="captured-dump",manifest_engine="mysql" if dialect=="postgresql" else "postgresql")
    add(dialect,"dump-insert-data",header+f"CREATE TABLE {table('parent')} ({table('id')} INTEGER);\nINSERT INTO {table('parent')} VALUES (1);\n",decision="refuse",reason="data-section",source_class="captured-dump")
    add(dialect,"dump-replace-data",header+f"REPLACE INTO {table('parent')} VALUES (1);\n",decision="refuse",reason="data-section",source_class="captured-dump")
    add(dialect,"dump-load-data",header+f"LOAD DATA INFILE '/neutral.csv' INTO TABLE {table('parent')};\n",decision="refuse",reason="data-section",source_class="captured-dump")
    add(dialect,"dump-copy-data",header+f"COPY {table('parent')} FROM stdin;\n1\n\\.\n",decision="refuse",reason="data-section",source_class="captured-dump")
    add(dialect,"quoted-data-words",header+f"-- INSERT INTO parent is text only\nCREATE TABLE {table('parent')} ({table('note')} TEXT DEFAULT 'INSERT; COPY; REPLACE; LOAD DATA');\n",objects=[object_("table","parent",table("parent")),object_("column","note",table("note"),relation="parent")],source_class="captured-dump")
    add(dialect,"generated-duplicate","// Code generated by sqlc. DO NOT EDIT.\nconst q = `SELECT * FROM parent`;\n",decision="gap",reason="generated-duplicate",source_class="generated-sql-go",manifest_engine=dialect)
    add(dialect,"missing-schema","",decision="refuse",reason="schema-artifact-missing",source_class="missing",manifest_engine=dialect,expected_checklist="request-schema-only-dump")
    add(dialect,"ambiguous-roots","SELECT * FROM parent;\n",decision="refuse",reason="ambiguous-schema-set",source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="a/sqlc.yaml",relations=["parent"]),dict(manifest="b/sqlc.yaml",relations=["parent"])])
    add(dialect,"name-only","SELECT * FROM parent;\n",sites=[site("parent",binding="name-only")],source_class="authored-query",manifest_engine=dialect,declaration_sets=[],expected_schema_state="schema-artifact-missing",note="Named authored usage may remain visible beside missing-schema checklist state; no bound/current declaration is invented.")
    add(dialect,"unknown-declaration","SELECT * FROM absent;\n",decision="gap",reason="unknown-declaration",source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent"])],expected_unresolved_sites=["absent"])
    add(dialect,"dynamic-identifier","SELECT * FROM ${table};\n",decision="gap",reason="dynamic-identifier",source_class="authored-query",manifest_engine=dialect)
    add(dialect,"unsupported-statement","GRANT SELECT ON parent TO neutral_role;\n",decision="gap",reason="unsupported-statement",**common)
    add(dialect,"missing-parser-position","SELECT * FROM parent;\n",decision="gap",reason="parser-gap",source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent"])],projection_fault="omit-source-position",note="Projection contract control; a library AST without an exact byte token cannot publish an ungrounded site.")
    add(dialect,"cte-select","WITH picked AS (SELECT * FROM parent) SELECT * FROM picked JOIN child ON true;\n",sites=[site("parent"),site("child")],source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent","child"])],note="picked is a lexical CTE alias, not a third physical table.")
    add(dialect,"insert-select","INSERT INTO child SELECT * FROM parent;\n",sites=[site("child",access="write"),site("parent")],source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent","child"])])
    add(dialect,"update-subquery","UPDATE child SET id = (SELECT id FROM parent);\n",sites=[site("child",access="read-write"),site("parent")],source_class="authored-query",manifest_engine=dialect,declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent","child"])])
    add(dialect,"malformed-string",f"CREATE TABLE {table('parent')} ({table('note')} TEXT DEFAULT 'unterminated);\n",decision="refuse",reason="malformed-input",**common)
    add(dialect,"input-byte-limit","x"*262144+"\n",decision="refuse",reason="resource-limit",**common)

add("postgresql","unquoted-ascii-fold","CREATE TABLE Foo (ID INTEGER);\n",objects=[object_("table","Foo",canonical_name="foo"),object_("column","ID",relation="Foo",canonical_name="id")],source_class="authored-schema",manifest_engine="postgresql")
add("postgresql","delete-using","DELETE FROM child USING parent WHERE child.id = parent.id;\n",sites=[site("child",access="read-write"),site("parent")],source_class="authored-query",manifest_engine="postgresql",declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent","child"])])
add("postgresql","on-conflict-update","INSERT INTO child (id) VALUES (1) ON CONFLICT (id) DO UPDATE SET id=EXCLUDED.id;\n",sites=[site("child",access="read-write")],source_class="authored-query",manifest_engine="postgresql",declaration_sets=[dict(manifest="sqlc.yaml",relations=["child"])])
add("postgresql","procedural-dollar-quote","DO $body$ BEGIN EXECUTE 'CREATE TABLE hidden (id integer)'; END $body$;\n",decision="gap",reason="procedural-sql",source_class="authored-schema",manifest_engine="postgresql",note="Dollar-quoted inner SQL never supplies a current hidden table.")
add("postgresql","dump-restrict-wrapper","-- PostgreSQL database dump\n-- Dumped by pg_dump version 18.6\n\\restrict neutralFixedKey\nSET statement_timeout = 0;\nCREATE TABLE parent (id integer);\n\\unrestrict neutralFixedKey\n",objects=[object_("table","parent"),object_("column","id",relation="parent")],source_class="captured-dump")
add("mysql","multi-table-delete","DELETE c FROM child c JOIN parent p ON p.id=c.id;\n",sites=[site("child",access="read-write"),site("parent")],source_class="authored-query",manifest_engine="mysql",declaration_sets=[dict(manifest="sqlc.yaml",relations=["parent","child"])],note="c target resolves through local alias only, no extra literal site.")
add("mysql","on-duplicate-update","INSERT INTO child (id) VALUES (1) ON DUPLICATE KEY UPDATE id=VALUES(id);\n",sites=[site("child",access="read-write")],source_class="authored-query",manifest_engine="mysql",declaration_sets=[dict(manifest="sqlc.yaml",relations=["child"])])
add("mysql","versioned-data-section","-- MySQL dump 10.13 Distrib 8.0.42\n/*!40101 INSERT INTO child VALUES (1) */;\n",decision="refuse",reason="data-section",source_class="captured-dump")
add("mysql","delimiter-procedure","DELIMITER $$\nCREATE PROCEDURE neutral_proc() BEGIN CREATE TABLE hidden(id INT); END$$\nDELIMITER ;\n",decision="gap",reason="procedural-sql",source_class="authored-schema",manifest_engine="mysql",note="Delimiter body remains one procedural envelope, no hidden table facts.")
add("mysql","prefix-generated-column","CREATE TABLE child (name VARCHAR(32), folded VARCHAR(32) GENERATED ALWAYS AS (LOWER(name)) STORED, KEY ix_name (name(8))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;\n",objects=[object_("table","child"),object_("column","name",relation="child"),object_("column","folded",relation="child"),object_("index","ix_name",relation="child",columns=["name"],prefix_lengths=[8])],source_class="authored-schema",manifest_engine="mysql",note="Generated expression/type and index prefix unit remain opaque source declarations; no server configuration/runtime semantics.")


def exact(raw,literal,occurrence):
    token=literal.encode()
    position=-1
    for _ in range(occurrence+1):
        position=raw.find(token,position+1)
        assert position>=0,(literal,occurrence)
    return dict(start=position,end=position+len(token),sha256=hashlib.sha256(token).hexdigest())


def main():
    target=ROOT/"fixtures/controls"
    target.mkdir(parents=True,exist_ok=True)
    out=[]
    for original in CASES:
        case=original.copy()
        raw=case.pop("sql").encode()
        path=target/(case["id"]+".sql")
        path.write_bytes(raw)
        case.update(source_path=str(path.relative_to(ROOT)),source_bytes=len(raw),source_sha256=hashlib.sha256(raw).hexdigest(),population="authored-neutral-control; excluded from public-corpus denominators")
        objects=[]
        for choice in case.pop("object_choices"):
            choice=choice.copy()
            literal=choice.pop("literal");occurrence=choice.pop("occurrence")
            choice.update(exact(raw,literal,occurrence),quoted=literal.startswith(('"','`')))
            if choice["name"]=="@":choice["name"]="@"+str(choice["start"])
            objects.append(choice)
        sites=[]
        for choice in case.pop("site_choices"):
            choice=choice.copy()
            literal=choice.pop("literal");occurrence=choice.pop("occurrence")
            choice.update(exact(raw,literal,occurrence),quoted=literal.startswith(('"','`')))
            sites.append(choice)
        case.update(expected_objects=objects,expected_sites=sites)
        out.append(case)
    # Strict UTF-8 admission controls retain invalid bytes as files, not a JSON
    # replacement character that would silently change the parser input.
    for dialect in ["postgresql","mysql"]:
        raw=b"CREATE TABLE bad (id INT);\xff"
        path=target/(dialect+"-invalid-utf8.bin");path.write_bytes(raw)
        out.append(dict(id=dialect+"-invalid-utf8",dialect=dialect,source_path=str(path.relative_to(ROOT)),source_bytes=len(raw),source_sha256=hashlib.sha256(raw).hexdigest(),source_class="authored-schema",manifest_engine=dialect,expected_decision="refuse",expected_reason="malformed-input",expected_objects=[],expected_sites=[],population="authored-neutral-control; excluded from public-corpus denominators"))
    result=dict(format="t261-controls-v1",stage="authored and labelled before candidate/grammar execution",parser_runs=0,recognizer_runs=0,cases=out)
    path=ROOT/"controls.json";path.write_text(json.dumps(result,indent=2,ensure_ascii=False)+"\n")
    print(json.dumps(dict(cases=len(out),postgresql=sum(c["dialect"]=="postgresql" for c in out),mysql=sum(c["dialect"]=="mysql" for c in out),sha256=hashlib.sha256(path.read_bytes()).hexdigest())))


if __name__=="__main__":main()
